import { cookies, headers } from 'next/headers';

export default function ThemeDisplay() {
  const cookieStore = cookies();
  const headersList = headers();

  const theme = cookieStore.get('theme')?.value || 'light';
  const acceptLanguage = headersList.get('accept-language') || 'en-US';

  const primaryLanguage = acceptLanguage.split(',')[0].split(';')[0];

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px', margin: '20px 0' }}>
      <h2>User Preferences</h2>
      <div style={{ marginBottom: '10px' }}>
        <strong>Current Theme:</strong> {theme}
      </div>
      <div style={{ marginBottom: '10px' }}>
        <strong>Preferred Language:</strong> {primaryLanguage}
      </div>
      <div style={{ fontSize: '0.9em', color: '#666', marginTop: '15px' }}>
        <p>Theme is read from the &quot;theme&quot; cookie. Defaults to &quot;light&quot; if not set.</p>
        <p>Language is extracted from the Accept-Language header.</p>
      </div>
    </div>
  );
}

