import ThemeDisplay from './theme-display';

export default function Home() {
  return (
    <main style={{ padding: '40px', maxWidth: '800px', margin: '0 auto' }}>
      <h1>User Preferences</h1>
      <p>This page displays your theme preference and preferred language.</p>
      <ThemeDisplay />
      <div style={{ marginTop: '30px', fontSize: '0.9em', color: '#555' }}>
        <h3>How it works:</h3>
        <ul>
          <li>The component reads the &quot;theme&quot; cookie to determine your theme preference</li>
          <li>If no theme cookie exists, it defaults to &quot;light&quot;</li>
          <li>It extracts your preferred language from the Accept-Language header</li>
          <li>Both values are displayed in the component above</li>
        </ul>
      </div>
    </main>
  );
}

